<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'
import { Search, BriefcaseBusiness, MapPin, CalendarDays, X } from 'lucide-vue-next'
import { projectsApi } from '../api/client'
import SectionTitle from '../components/SectionTitle.vue'
import UiState from '../components/UiState.vue'
import PaginationBar from '../components/PaginationBar.vue'
import BaseModal from '../components/BaseModal.vue'
const rows=ref<any[]>([]),selected=ref<any>(null),loading=ref(false),error=ref(''),total=ref(0),page=ref(1),pageSize=9,search=ref(''),stage=ref(''),industry=ref('')
async function load(){loading.value=true;error.value='';try{const r=await projectsApi.list({search:search.value||undefined,stage:stage.value||undefined,industry:industry.value||undefined,page:page.value,page_size:pageSize});rows.value=r.items;total.value=r.total}catch(e:any){error.value=e.userMessage||'Не удалось получить проекты'}finally{loading.value=false}}
watch([page,stage,industry],load);onMounted(load)
const money=(n:any)=>n==null?'—':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',notation:'compact',maximumFractionDigits:1}).format(n)
let timer:ReturnType<typeof setTimeout>
function searchChanged(){clearTimeout(timer);page.value=1;timer=setTimeout(load,300)}
</script>
<template><main class="page"><SectionTitle title="Инвестиционный навигатор" subtitle="Проекты и инициативы для развития коммерческого портфеля."/><section class="panel filter-panel"><div class="filters-grid project-filters"><label class="field search-field"><span>Поиск проекта</span><div class="input-icon"><Search/><input v-model="search" placeholder="Название или описание" @input="searchChanged"/></div></label><label class="field"><span>Стадия проекта</span><select v-model="stage"><option value="">Все стадии</option><option value="idea">Идея</option><option value="evaluation">Оценка</option><option value="planning">Планирование</option><option value="active">В реализации</option><option value="completed">Завершён</option></select></label><label class="field"><span>Отрасль</span><input v-model="industry" placeholder="Любая отрасль"/></label><button class="btn btn-secondary filter-reset" @click="search='';stage='';industry='';page=1;load()"><X :size="15"/> Сбросить</button></div></section><div class="projects-heading"><div><h2>Портфель проектов</h2><p>Найдено: {{total.toLocaleString('ru-RU')}}</p></div><span class="subtle-label">Карточный вид</span></div><UiState :loading="loading" :error="error" :empty="!rows.length" empty-text="Проекты не найдены. Попробуйте изменить фильтры." @retry="load"><div class="projects-grid"><button v-for="p in rows" :key="p.id" class="project-card" @click="selected=p"><div class="project-card-top"><div class="project-icon"><BriefcaseBusiness/></div><span class="stage-pill">{{p.stage||'Стадия не указана'}}</span></div><h3>{{p.name}}</h3><p class="project-description">{{p.description||'Описание проекта не предоставлено.'}}</p><div class="project-meta"><span><MapPin :size="14"/>{{p.region||p.industry||'Без категории'}}</span><span><CalendarDays :size="14"/>{{p.updated_at?new Date(p.updated_at).toLocaleDateString('ru-RU'):'Дата не указана'}}</span></div><div class="project-bottom"><div><small>Инвестиционный объём</small><strong>{{money(p.investment_amount)}}</strong></div><span class="view-link">Подробнее <span>↗</span></span></div></button></div></UiState><PaginationBar v-if="!loading&&!error&&total>pageSize" :page="page" :page-size="pageSize" :total="total" @change="page=$event"/><BaseModal v-if="selected" title="Детали проекта" wide @close="selected=null"><div class="project-detail"><span class="stage-pill">{{selected.stage||'Стадия не указана'}}</span><h3>{{selected.name}}</h3><p>{{selected.description||'Описание отсутствует.'}}</p><div class="detail-grid"><div><small>Отрасль</small><strong>{{selected.industry||'—'}}</strong></div><div><small>Регион</small><strong>{{selected.region||'—'}}</strong></div><div><small>Инвестиционный объём</small><strong>{{money(selected.investment_amount)}}</strong></div><div><small>Ожидаемый эффект</small><strong>{{selected.expected_return??'—'}}</strong></div><div><small>Ответственный</small><strong>{{selected.owner||'—'}}</strong></div><div><small>Срок</small><strong>{{selected.deadline||'—'}}</strong></div></div></div><template #footer><button class="btn btn-secondary" @click="selected=null">Закрыть</button></template></BaseModal></main></template>